public class ClassChainReporterTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        check("depth of a plain Object", 0, ClassChainReporter.depth(new Object()));
        check("depth of a String", 1, ClassChainReporter.depth("hi"));
        check("depth of an Integer", 2, ClassChainReporter.depth(Integer.valueOf(3)));
        check("depth of null", -1, ClassChainReporter.depth(null));

        check("chain of a String", "String -> Object", ClassChainReporter.chain("hi"));
        check("chain of an Integer", "Integer -> Number -> Object", ClassChainReporter.chain(Integer.valueOf(3)));
        check("chain of null", "none", ClassChainReporter.chain(null));

        String kinds = ClassChainReporter.isKindOf(Integer.valueOf(3), "Number")
                + "," + ClassChainReporter.isKindOf("hi", "Number")
                + "," + ClassChainReporter.isKindOf("hi", "Object")
                + "," + ClassChainReporter.isKindOf(null, "Object");
        check("isKindOf walks the whole line", "true,false,true,false", kinds);

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
