/**
 * TASK: Complete ClassChainReporter. Every method walks UP the class
 * hierarchy with getClass() and then getSuperclass(), which returns null
 * once you pass java.lang.Object.
 *
 * Rules:
 *   - depth(o) counts how many classes sit ABOVE the object's own class:
 *     new Object() -> 0, "hi" -> 1 (String -> Object),
 *     Integer.valueOf(3) -> 2 (Integer -> Number -> Object); null -> -1
 *   - chain(o) names the whole line with " -> " between the simple names:
 *     "Integer -> Number -> Object"; null -> "none"
 *   - isKindOf(o, simpleName) is true when any class in that line has the
 *     given simple name; null object or null name -> false
 *
 * Example: isKindOf(Integer.valueOf(3), "Number") is true while
 *   isKindOf("hi", "Number") is false.
 */
public class ClassChainReporter {

    public static int depth(Object o) {
        if (o == null) {
            return -1;
        }
        int steps = 0;
        Class<?> current = o.getClass().getSuperclass();
        while (current != null) {
            steps++;
            current = current.getSuperclass();
        }
        return steps;
    }

    public static String chain(Object o) {
        if (o == null) {
            return "none";
        }
        StringBuilder text = new StringBuilder();
        Class<?> current = o.getClass();
        while (current != null) {
            if (text.length() > 0) {
                text.append(" -> ");
            }
            text.append(current.getSimpleName());
            current = current.getSuperclass();
        }
        return text.toString();
    }

    public static boolean isKindOf(Object o, String simpleName) {
        if (o == null || simpleName == null) {
            return false;
        }
        Class<?> current = o.getClass();
        while (current != null) {
            if (current.getSimpleName().equals(simpleName)) {
                return true;
            }
            current = current.getSuperclass();
        }
        return false;
    }
}
